def _parse(version):
    """Parse a semantic version string into comparable components."""
    without_build = version.split('+', 1)[0]
    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
        pre = prerelease.split('.')
    else:
        core = without_build
        pre = None

    major, minor, patch = (int(part) for part in core.split('.'))
    return major, minor, patch, pre


def _compare_prerelease(a, b):
    for x, y in zip(a, b):
        x_numeric = x.isdigit()
        y_numeric = y.isdigit()

        if x_numeric and y_numeric:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_numeric != y_numeric:
            # Numeric identifiers have lower precedence than alphanumeric ones.
            return -1 if x_numeric else 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _compare_versions(a, b):
    amaj, amin, apat, apre = _parse(a)
    bmaj, bmin, bpat, bpre = _parse(b)

    for x, y in ((amaj, bmaj), (amin, bmin), (apat, bpat)):
        if x != y:
            return -1 if x < y else 1

    # A version without a pre-release has higher precedence.
    if apre is None and bpre is None:
        return 0
    if apre is None:
        return 1
    if bpre is None:
        return -1

    return _compare_prerelease(apre, bpre)


def sort_versions(vs):
    """Return semantic version strings sorted by SemVer precedence (lowest first)."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
